import { useEffect, useState } from 'react';
import mystyle from './ShowForm.module.css'
import axios from 'axios';
import { useParams } from 'react-router';

const ShowForm = () => {

    const { id } = useParams();

    const [alert, setAlert] = useState(false)
    const [answers, setAnswers] = useState({});

    const [fdata, setFdata] = useState()
    console.log(fdata)

    useEffect(() => {
        axios.get(`https://formtask-obmh.onrender.com/${id}`).then((success) => {
            console.log(success)
            setFdata(success.data)
        }).catch((error) => {
            console.log(error)
        })
    }, [])

    const handleAnswer = (question, value) => {
        setAnswers((prev) => ({
            ...prev,
            [question]: value
        }));
    };

    const getFormdata = () => {
        console.log("data got it")
        console.log(answers)
        console.log(id)
        axios.post("https://formtask-obmh.onrender.com/addrespon", { id, answers }).then((success) => {
            console.log(success)
            setAlert(true)
        }).catch((error) => {
            console.log(error)
        })
    }

    const close = () => {
        setAlert(false)
    }
    return (
        <div className={mystyle.main}>

            {
                alert && <div className={mystyle.alert}><p>Data sava successfully</p><button onClick={close}>Ok</button></div>
            }
            <div className={mystyle.sub}>
                <h1>this is the user form</h1>

                <div className={mystyle.di1}>
                    {fdata && (
                        <>
                            <h2>{fdata.title}</h2>
                            <p>{fdata.fdis}</p>
                        </>
                    )}
                </div>
                <div className={mystyle.di2}>
                    {fdata?.questions?.map((q, index) => (
                        <div key={index}>

                            <label>{q.question}</label>

                            {q.type === "text" && (
                                <input className={mystyle.text1} type="text" placeholder='your answer' onChange={(e) =>
                                    handleAnswer(q.question, e.target.value)
                                } />
                            )}

                            {q.type === "email" && (
                                <input type="email" className={mystyle.text1} placeholder='your answer' onChange={(e) =>
                                    handleAnswer(q.question, e.target.value)
                                } />
                            )}

                            {q.type === "number" && (
                                <input type="number" className={mystyle.text1} placeholder='your answer' onChange={(e) =>
                                    handleAnswer(q.question, e.target.value)
                                } />
                            )}

                            {q.type === "radio" &&
                                q.options.map((option, i) => (
                                    <div key={i}>
                                        <label>
                                            <input
                                                type="radio"
                                                name={`question-${index}`}
                                                value={option}
                                                onChange={(e) =>
                                                    handleAnswer(q.question, e.target.value)
                                                }
                                            />
                                            {option}
                                        </label>
                                    </div>
                                ))}

                            {q.type === "select" && (
                                <select onChange={(e) =>
                                    handleAnswer(q.question, e.target.value)
                                }>
                                    {q.options.map((option, i) => (
                                        <option key={i} value={option}>
                                            {option}
                                        </option>
                                    ))}
                                </select>
                            )}


                        </div>


                    ))}
                    <button className={mystyle.btn1} onClick={getFormdata}> Sava </button>
                </div>
            </div>
        </div>
    )
}

export default ShowForm;