import axios from "axios";
import { useEffect, useState } from "react";
import { useParams } from "react-router";
import mystyle from './Userrdata.module.css'


const Userrdata = () => {

    const { id } = useParams()

    const [rdata, setRdata] = useState([])
    console.log(rdata)

    useEffect(() => {
        axios.get(`https://formtask-obmh.onrender.com/showuserr/${id}`).then((success) => {
            console.log(success)
            setRdata(success.data)
        }).catch((error) => {
            console.log(error)
        })
    }, [])

    return (
        <div className={mystyle.main} >

            <div className={mystyle.sub1}>
                <h1>here show user response</h1>

                {
                    rdata.map((d) => (
                        <div key={d._id} className={mystyle.sub}>
                            <p>Fromid:{d._id}</p>
                            {Object.entries(d.answers).map(([key, value]) => (
                                <div key={key}>
                                    <strong>{key}:</strong> {value}
                                </div>
                            ))}
                        </div>
                    ))
                }
            </div >
        </div >
    )
}

export default Userrdata;