import { useState } from "react"
import mystyle from "./InfoBodyform.module.css"
import axios from 'axios';

const InfoBodyform = () => {


    const [alret, setAlert] = useState(false)
    const [title, setTitle] = useState();
    const [fdis, setFdis] = useState();
    const [questions, setQuestions] = useState([
        {
            question: "",
            type: "",
            options: []
        }
    ]);


    const addQuestion = () => {
        setQuestions([
            ...questions,
            {
                question: "",
                type: ""
            }
        ]);
    };

    const handleQuestionChange = (index, value) => {
        const updated = [...questions];
        updated[index].question = value;
        setQuestions(updated);
    };

    const handleTypeChange = (index, value) => {
        const updated = [...questions];
        updated[index].type = value;
        setQuestions(updated);
    };

    const removeQuestion = (index) => {
        const updated = [...questions];
        updated.splice(index, 1);
        setQuestions(updated);
    };


    const addOption = (index) => {
        const updated = [...questions];
        updated[index].options.push("");
        setQuestions(updated);
    };

    const handleOptionChange = (qIndex, opIndex, value) => {
        const updated = [...questions];
        updated[qIndex].options[opIndex] = value;
        setQuestions(updated);
    };


    const getTitle = (event) => {
        setTitle(event.target.value)
    }

    const getFdis = (event) => {
        setFdis(event.target.value)
    }


    const getFormdata = () => {
        console.log(title)
        console.log(fdis)
        console.log(questions)

        axios.post("https://formtask-obmh.onrender.com/adddata", { title, fdis, questions }).then((success) => {
            console.log(success)
            if (success.data.length === 1) {
                setAlert(true)
            }
        }).catch((error) => {
            console.log(error)
        })

    }

    const close = () => {
        setAlert(false)
    }

    return (
        <div className={mystyle.main} >

            {
                alret && <div className={mystyle.alert}><p>From Sava successfully plz check in resopose</p><button onClick={close}>ok</button></div>
            }
            <div className={mystyle.sub}>
                <input className={mystyle.title} type="text" placeholder=" Form Title" onChange={getTitle} />
                <input className={mystyle.title} type="text" placeholder="Form Discription" onChange={getFdis} />

                {/* <div className={mystyle.sub1}>
                    <input placeholder="Untitle question" />
                    <select onChange={getType}>
                        <option value="">select type</option>
                        <option value="text">text</option>
                        <option value="number">Number</option>
                        <option value="email">Email</option>
                        <option value="select">select</option>
                        <option value="radio">radio</option>

                    </select >
                </div> */}

                <div className={mystyle.sub1}>
                    {
                        questions.map((q, index) => (
                            <div key={index} className={mystyle.din}>

                                <input
                                    placeholder="Untitle Question"
                                    value={q.question}
                                    onChange={(e) =>
                                        handleQuestionChange(index, e.target.value)
                                    }
                                />

                                <select
                                    value={q.type}
                                    onChange={(e) =>
                                        handleTypeChange(index, e.target.value)
                                    }
                                >
                                    <option value="">Select Type</option>
                                    <option value="text">Text</option>
                                    <option value="number">Number</option>
                                    <option value="email">Email</option>
                                    <option value="radio">Radio</option>
                                    <option value="select">Select</option>
                                </select>

                                {/* Preview */}

                                {q.type === "text" && (
                                    <input type="text" placeholder="your answer" />
                                )}

                                {q.type === "number" && (
                                    <input type="number" placeholder="your answer" />
                                )}

                                {q.type === "email" && (
                                    <input type="email" placeholder="your answer" />
                                )}

                                {(q.type === "radio" || q.type === "select") && (
                                    <div>
                                        {q.options.map((option, opIndex) => (
                                            <input
                                                key={opIndex}
                                                type="text"
                                                placeholder={`Option ${opIndex + 1}`}
                                                value={option}
                                                onChange={(e) =>
                                                    handleOptionChange(
                                                        index,
                                                        opIndex,
                                                        e.target.value
                                                    )
                                                }
                                            />
                                        ))}

                                        <button
                                            type="button"
                                            onClick={() => addOption(index)}
                                        >
                                            Add Option
                                        </button>
                                    </div>
                                )}
                                <button className={mystyle.delbtn}
                                    type="button"
                                    onClick={() => removeQuestion(index)}
                                >
                                    Delete
                                </button>
                            </div>
                        ))
                    }


                </div>
                <button onClick={addQuestion} className={mystyle.addin}>
                    Add Question
                </button>

                <div className={mystyle.savadi}>
                    <button className={mystyle.savabtn} onClick={getFormdata}>Sava Data</button>
                </div>
            </div>

        </div>
    )
}

export default InfoBodyform;