import { useNavigate } from 'react-router';
import mystyle from './ConNav.module.css'

const ConNav = () => {

    const naviget = useNavigate()


    const getInfo = () => {
          naviget('infobodyform')
    }

    const getRespons = () => {
        naviget("response")
    }



    return (
        <div className={mystyle.main}>
            <div className={mystyle.sub}>
                <p onClick={getInfo}>Questions</p>
                <p onClick={getRespons}>Respoens</p>
                <p>setting</p>
            </div>

        </div>
    )
}

export default ConNav;