import { Outlet } from 'react-router';
import mystyle from './DashBoard.module.css';
import DashNav from './Navbar/DashNav';


const DashBord = () => {

    return (
        <div className={mystyle.main}>
            <DashNav />
            <div>
                <Outlet />
            </div>


        </div>
    )
}

export default DashBord;