
import './App.css';
import DashBord from './component/DashBoard';
import { createBrowserRouter } from "react-router";
import { RouterProvider } from "react-router/dom";
import AllForms from './component/Forms/AllForms';
import Blankform from './component/Forms/Blankform/Blankform';
import ConInfoform from './component/Forms/coninfo/ConInfoform';
import InfoBodyform from './component/Forms/coninfo/InfoBodyform';
import ShowForm from './component/showuserform/ShowForm';
import Response from './component/Forms/coninfo/Response';
import Userrdata from './component/Forms/coninfo/Userrdata';

function App() {

  const router = createBrowserRouter([
    {
      path: '/',
      element: <DashBord />,
      children: [

        {
          index: true,
          element: <AllForms />
        },

        {
          path: "allforms",
          element: <AllForms />
        }

      ]
    },

    {
      path: "/blanckform",
      element: <Blankform />
    },

    {
      path: "/conInfo",
      element: <ConInfoform />,
      children: [

        {
          index: true,
          element: <InfoBodyform />
        },

        {
          path: "infobodyform",
          element: <InfoBodyform />
        },
        {
          path: "response",
          element: <Response />
        }

      ]
    },

    {
      path: '/showuserform/:id',
      element: <ShowForm />
    },

    {
      path: "/Userrdata/:id",
      element: <Userrdata />
    }


  ], {
    basename: '/formtask'
  })
  return (
    <div className="App">
      <RouterProvider router={router} />

    </div>
  );
}

export default App;
